import java.util.*; abstract class Ticket09{abstract double price();abstract String type();double total(){return price()+20;}} class Regular09 extends Ticket09{double price(){return 150;}String type(){return "Regular";}} class Premium09 extends Ticket09{double price(){return 250;}String type(){return "Premium";}} class Recliner09 extends Ticket09{double price(){return 400;}String type(){return "Recliner";}} public class Week09Problem01{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();Ticket09 a=t.equals("REGULAR")?new Regular09():t.equals("PREMIUM")?new Premium09():new Recliner09();System.out.printf("%s: %.2f%n",a.type(),a.total());total+=a.total();}System.out.printf("Total: %.2f%n",total);}}